function drawWatch(uid){const u=UNIT[uid],e=EP[uid];zCur='watch-'+uid;slWho={A:e.l,B:e.r};
 const t=zShell(`🎬 Watch: ${u.name}`,`<div class="w-tag" id="wTag">🎬 Episode</div>${slSceneHTML(e.l,e.r)}<div class="sl-choices" id="slCh" hidden></div><p class="sl-note" id="slNote" hidden></p>`);
 const play=async lines=>{for(const [s,txt,ex,th] of lines){if(!zLive(t))return false;slHush(s==='A'?'B':'A');await slSay(s,txt,ex);if(th){slThink(s,th);await slWait(1900);}await slWait(250);}return zLive(t);};
 const tag=(txt,cls)=>{const g=$id('wTag');if(g){g.textContent=txt;g.className='w-tag '+(cls||'');}};
 (async()=>{await slWait(300);if(!await play(e.setup))return;tag('😬 Oops version','oops');if(!await play(e.bad))return;await slWait(500);
  tag('⏪ Rewind…','rew');slHush('A');slHush('B');slUnthink();slExpr('A','neutral');slExpr('B','neutral');$id('slScene').classList.add('rewind');await slWait(1300);if(!zLive(t))return;$id('slScene').classList.remove('rewind');
  tag('✨ Super version','super');if(!await play(e.setup))return;if(!await play(e.good))return;slFx(['💖','✨','⭐'],10);await slWait(700);if(!zLive(t))return;
  tag('🤔 Your turn');const ch=$id('slCh');ch.hidden=false;ch.innerHTML=`<p class="zg-ask">${e.q}</p><button class="sl-choice c0" data-v="0">😬 The oops version</button><button class="sl-choice c1" data-v="1">✨ The super version</button><button class="sl-choice c2" data-r="1">🔁 Watch again</button>`;if(window.RikiFit)RikiFit();
  ch.querySelector('[data-r]').onclick=()=>drawWatch(uid);
  ch.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>{if(b.dataset.v==='1'){audio('good');slGain(1);(zSave.done[uid]=zSave.done[uid]||{}).watch=1;zPut();ch.querySelectorAll('button').forEach(x=>x.disabled=true);(async()=>{ch.innerHTML=`<div class="w-steps"><b>✨ Riki’s ${u.name} trick</b>${u.steps.map((s,i)=>`<span data-s="${i}">${s[0]} ${s[1]}</span>`).join('')}</div>`;slHush('B');for(let i=0;i<u.steps.length;i++){if(!zLive(t))return;const el=ch.querySelector(`[data-s="${i}"]`);if(el)el.classList.add('on');await slSay('A',u.steps[i][1]+'.',i===u.steps.length-1?'excited':'happy');}if(zLive(t))zDone(t,'🎬 Great watching! Now try a game.',()=>drawWatch(uid),2);const ag=$id('zAgain');if(ag){ag.textContent='🎮 Back to games';ag.onclick=()=>{audio('tap');newHub();};}})();}else{audio('tap');zMiss();zNote('Hmm. Look at how the other person felt in their thought bubble.');}});})();}

