 const t=zShell(`🪜 Steps: ${u.name}`,`${slSceneHTML('riki',EP[uid].r)}<ol class="st-ladder" id="stL">${u.steps.map((_,i)=>`<li data-n="${i}"><span>${i+1}</span></li>`).join('')}</ol><div class="zr-cards" id="stC">${cards.map(c=>`<button class="zr-card" data-i="${c[2]}">${c[0]} ${c[1]}</button>`).join('')}</div><p class="sl-note" id="slNote">What comes first? Tap the steps in order.</p>`);
 if(easy(uid))hintBtn($id('zRoot'),()=>document.querySelector(`#stC [data-i="${at}"]`));
